/**
 * De åtta formvalen i UI:t — samma som WinBliss² "workbench 2" (Håkan Larsson,
 * 2026-09-24: "obestämd och plural bestämd" prövades samma kväll och
 * släpptes — bestämd ensam är vad användarna behöver). Tecknet #0–#7 är
 * samma tangentgenväg som där ("gå #2" -> går).
 */
const FORM_CHOICES = [
  { key: '', sv: 'ingen' },
  { key: 'action', sv: 'verb' },
  { key: 'present_action', sv: 'presens' },
  { key: 'past_action', sv: 'dåtid' },
  { key: 'future_action', sv: 'futurum' },
  { key: 'plural', sv: 'plural' },
  { key: 'imperative_form', sv: 'uppmaning' },
  { key: 'definite_form', sv: 'bestämd' },
];

/** Tempus/verbform är ömsesidigt uteslutande; plural och bestämd kan kombineras. */
const IND_TENSE = new Set(['action', 'present_action', 'past_action', 'future_action', 'imperative_form']);
const IND_ORDER = ['action', 'present_action', 'past_action', 'future_action', 'imperative_form', 'plural', 'definite_form'];

/** Kanonisk ordning: tempus först, sen plural, sen bestämd; okända nycklar (AI:n kan föreslå t.ex. adverb) behålls efter. */
function indJoin(keys) {
  const known = IND_ORDER.filter((k) => keys.includes(k));
  const other = keys.filter((k) => k && !IND_ORDER.includes(k));
  return known.concat(other);
}

/** Växla en form: '' rensar allt; ett tempus ersätter ett annat; plural/bestämd läggs till eller tas bort. */
function indToggle(keys, key) {
  if (!key) return [];
  let out = keys.slice();
  if (out.includes(key)) out = out.filter((k) => k !== key);
  else {
    if (IND_TENSE.has(key)) out = out.filter((k) => !IND_TENSE.has(k));
    out.push(key);
  }
  return indJoin(out);
}

/**
 * Grammar — indikatorinventering, alias och platsdetektering.
 * Fundamental Rules 4.3.3/7.1: indikatorn hänger på indikatorlinjen (y=4)
 * ovanför ordets FÖRSTA Bliss-tecken; 4.3.4: höga glyfer trycker upp den
 * till den höga indikatorlinjen (y=0).
 */
class Grammar {
  constructor(records = INDICATOR_RECORDS) {
    this.indicators = new Map();
    this.sigs = new Set();
    for (const rec of records) {
      const m = rec.name.match(/^indicator_\(([^)]+)\)(.*)$/);
      if (!m || /OLD/.test(m[2])) continue;
      this.indicators.set(m[1], rec);
      for (const e of rec.e) this.sigs.add(e[T.TYPE] + e[T.SUB]);
    }
    this.alias = {
      action: 'action', verb: 'action',
      present: 'present_action',
      past: 'past_action', future: 'future_action',
      continuous: 'continuous_form', progressive: 'continuous_form',
      passive: 'passive', past_passive: 'past_passive', future_passive: 'future_passive',
      conditional: 'conditional', would: 'conditional',
      plural: 'plural', things: 'thing_plural',
      thing: 'thing', noun: 'thing',
      description: 'description', adjective: 'description', adverb: 'adverb',
      imperative: 'imperative_form', command: 'imperative_form',
      definite: 'definite_form', diminutive: 'diminutive_form',
      past_participle: 'past_participle_1', present_participle: 'present_participle',
    };
  }
  resolve(name) {
    const k = String(name).toLowerCase().trim().replace(/[ -]/g, '_');
    return this.indicators.get(k) || this.indicators.get(this.alias[k]) || null;
  }
  isIndicatorElement(e) {
    if (!this.sigs.has(e[T.TYPE] + e[T.SUB])) return false;
    if (e[T.Y] === 4) return true;
    return e[T.Y] === 0 && e[T.TYPE] + e[T.SUB] !== 'W1';
  }
  inventory() {
    return [...this.indicators.entries()].map(([key, r]) => ({ key, id: r.id, gloss: r.name }));
  }
}


/** Bounding box (i halv-enheter, samma skala som x/y i .wbs) via den riktiga
 * renderaren — strokeUnits:0 tar bort penn-marginalen så måtten blir exakta,
 * i stället för att porta Node-versionens egna bågmatematik (arcPoints/pathBBox). */
function unitBBox(elements) {
  const svg = window.blissSVG({ e: elements }, { unit: 1, strokeUnits: 0, color: '#000' });
  const m = svg.match(/viewBox="([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+)"/);
  if (!m) return { minX: 0, maxX: 0, w: 0 };
  const vx = parseFloat(m[1]), vw = parseFloat(m[3]);
  return { minX: vx / 100, maxX: (vx + vw) / 100, w: vw / 100 };
}

/** Låda MED blissSVG:s standardpenn-marginal (35 enh) — samma mått workbench 2 räknar luft med. */
function penBox(els) {
  const svg = window.blissSVG({ e: els }, { unit: 4, color: 'currentColor' });
  const m = svg.match(/viewBox="([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+)"/);
  return { vx: +m[1], vw: +m[3] };
}

/**
 * Delarna i en sammansatt indikator behåller en ÅTTONDEL kvadrat synlig luft
 * mellan sig (Håkan Larssons dom, 2026-09-24 — Fundamental Rules ger 1/8
 * kvadrat mellan siffror, 4.3.5, och säger inget om insidan av en indikator).
 * BCI:s egen post för present_action förankrar sina två bågar en halvenhet
 * isär, vilket vid pennbredd gör att de rör vid varandra. Posten lämnas som
 * BCI levererar den; det här är en renderingsregel ovanpå. Gäller bara delar
 * på samma y (sida vid sida) — diminutivformens staplade streck lämnas orörda.
 */
function indParts(partsIn) {
  const parts = partsIn.map((e) => e.slice());
  const pad = 35;               // blissSVG:s penn-marginal (0.35 enh * g=100)
  const want = 100 + pad;       // 1/8 kvadrat luft bortom pennan
  for (let i = 1; i < parts.length; i++) {
    if (parts[i][T.Y] !== parts[i - 1][T.Y]) continue;
    const a = penBox([parts[i - 1]]), b = penBox([parts[i]]);
    const gapNow = (b.vx + pad) - (a.vx + a.vw - pad);   // geometriskt avstånd mellan bläckbanorna
    if (gapNow < want) {
      const dx = (want - gapNow) / 100;
      for (let j = i; j < parts.length; j++) parts[j][T.X] += dx;
    }
  }
  return parts;
}

/** Hela formens indikatorer sida vid sida, vänster till höger, med luft enligt indParts. */
function indRecordParts(recs) {
  const e = [];
  let xNext = 0;
  for (const rec of recs) {
    const x0 = Math.min(...rec.e.map((el) => el[T.X]));
    const parts = rec.e.map((el) => { const c = el.slice(); c[T.X] += xNext - x0; return c; });
    e.push(...parts);
    xNext = Math.max(...parts.map((el) => el[T.X])) + 1;   // indParts öppnar sen luften
  }
  return indParts(e);
}

/** Indikatortecknets egen bild (för knappar) — ritat av motorn ur den riktiga BCI-posten. */
function indicatorGlyph(grammar, key, unit = 2.4) {
  const rec = grammar.resolve(key);
  if (!rec) return '';
  return window.blissSVG({ e: indRecordParts([rec]) }, { unit, color: 'currentColor' });
}

/**
 * items: [{ id?, gloss?, text?, indicators?: [names], replace_indicators?: bool }]
 * Returns { words, problems } — words carry per-word tupelelementlistor,
 * klara för blissSVG. Inget gissas: omatchade ord och okända indikatorer
 * rapporteras i `problems`, ersätts aldrig tyst.
 */
function composeSentence(vocab, grammar, items) {
  const words = [], problems = [];
  for (const it of items) {
    let base = null;
    if (it.id != null) base = vocab.byId.get(+it.id) || null;
    else if (it.text) {
      const zh = it.zheight || 6;
      base = { id: 0, name: it.text, e: [['Z', 1, 1, 0, 0, 16 - zh, 0, 0, it.text, 0, zh]] };
    }
    if (!base) { problems.push(`inget BCI-AV-id för ${it.id != null ? 'id ' + it.id : JSON.stringify(it)}`); continue; }

    let els = base.e.map((e) => e.slice());
    const indNames = indJoin((it.indicators || []).filter(Boolean));
    if (indNames.length) {
      const oldInds = els.filter((e) => grammar.isIndicatorElement(e));
      if (it.replace_indicators !== false) els = els.filter((e) => !grammar.isIndicatorElement(e));

      const recs = [];
      for (const n of indNames) {
        const rec = grammar.resolve(n);
        if (rec) recs.push(rec);
        else problems.push(`okänd grammatisk markör "${n}" (${base.name})`);
      }

      if (recs.length) {
        const parts = indRecordParts(recs);
        const bj = unitBBox(parts);
        let cx, indY;
        if (oldInds.length && it.replace_indicators !== false) {
          const ob = unitBBox(oldInds);
          cx = (ob.minX + ob.maxX) / 2;             // ärver BCI:s egen placering
          indY = oldInds[0][T.Y];
        } else {
          const bb = unitBBox(els.length ? els : base.e);
          cx = bb.minX + Math.min(bb.maxX - bb.minX, 8) / 2;
          const minY = Math.min(
            ...(els.length ? els : base.e).filter((e) => !grammar.isIndicatorElement(e)).map((e) => e[T.Y])
          );
          indY = minY < 4 ? 0 : 4;                   // 4.3.4: höga glyfer -> tall-indicator line
        }
        const xLeft = Math.round((cx - bj.w / 2) * 2) / 2;
        const dx = xLeft - bj.minX;
        const y0 = Math.min(...parts.map((e) => e[T.Y]));
        for (const e of parts) {
          const ne = e.slice();
          ne[T.X] = e[T.X] + dx;
          ne[T.Y] = e[T.Y] + (indY - y0);            // hela gruppen flyttas som en
          els.push(ne);
        }
      }
    }
    words.push({ id: base.id, name: base.name, e: els, indicators: indNames, label: it.label });
  }
  return { words, problems };
}

window.BlissGrammar = { INDICATOR_RECORDS, FORM_CHOICES, IND_TENSE, indJoin, indToggle, Grammar, indicatorGlyph, composeSentence };
